    t[OP_ADD as usize] = Some(st_OP_ADD);
    t[OP_SUB as usize] = Some(st_OP_SUB);
    t[OP_MUL as usize] = Some(st_OP_MUL);
    t[OP_DIV as usize] = Some(st_OP_DIV);
    t[OP_I_DIV as usize] = Some(st_OP_I_DIV);
    t[OP_MOD as usize] = Some(st_OP_MOD);
    t[OP_POW as usize] = Some(st_OP_POW);
    t[OP_ADD_K as usize] = Some(st_OP_ADD_K);
    t[OP_SUB_K as usize] = Some(st_OP_SUB_K);
    t[OP_MUL_K as usize] = Some(st_OP_MUL_K);
    t[OP_DIV_K as usize] = Some(st_OP_DIV_K);
    t[OP_I_DIV_K as usize] = Some(st_OP_I_DIV_K);
    t[OP_MOD_K as usize] = Some(st_OP_MOD_K);
    t[OP_POW_K as usize] = Some(st_OP_POW_K);
    t[OP_AND as usize] = Some(st_OP_AND);
    t[OP_OR as usize] = Some(st_OP_OR);
    t[OP_AND_K as usize] = Some(st_OP_AND_K);
    t[OP_OR_K as usize] = Some(st_OP_OR_K);
    t[OP_CONCAT as usize] = Some(st_OP_CONCAT);
    t[OP_NOT as usize] = Some(st_OP_NOT);
    t[OP_MINUS as usize] = Some(st_OP_MINUS);
    t[OP_LENGTH as usize] = Some(st_OP_LENGTH);
    t[OP_NEW_TABLE as usize] = Some(st_OP_NEW_TABLE);
    t[OP_DUP_TABLE as usize] = Some(st_OP_DUP_TABLE);
    t[OP_SET_LIST as usize] = Some(st_OP_SET_LIST);
    t[OP_FOR_N_PREP as usize] = Some(st_OP_FOR_N_PREP);
    t[OP_FOR_N_LOOP as usize] = Some(st_OP_FOR_N_LOOP);
